// per weight than the GEMM it agrees with. That is exactly
// `llm_moe_gemv.comp`'s position against `llm_moe_gemm.comp` over the same
// format, and it is measured rather than asserted (TestHeadQ4Agrees).
//
// A lane reads its own column's record into a register and refreshes it when
// the split crosses a super-block — 256 k, sixteen k-tiles, four steps of
// this loop — so the records cost the format's own 12.5% and not eight times
// that.
//
// **ROWS is P5b, and it is the whole of what a verification pass needs.**
// D15 refuses this kernel above one token because a sixteen-row fragment
// holding one row is the *reason* it beats the GEMM — but the refusal was
// about the GEMM's shape, not about a dot product's, and a dot product
// extends to R rows for nothing: the weight is read once and multiplied into
// R accumulators against R rows of A. P5 measured what that is worth
// (research/p5-mtp-rollback.md): at two tokens the GEMM the host falls back
// to costs this projection **1.9-3.4x** on *identical* weight bytes, because
// its row block is sixteen to sixty-four rows with two real ones in it.
//
// It is a **specialization constant** rather than a `-D`, so one module
// serves every row count and the thirty-odd `.spv` of this family do not
// double. `MAXROWS` is the compile-time bound the accumulators are sized by;
// `ROWS <= MAXROWS` is checked by the host, and the `r < ROWS` guards fold
// away when the pipeline is specialized. P5a says the speculation optimum is
// depth 1 — a two-row verification pass — so MAXROWS is 2; P6's batching is
// the reason it is written as a bound rather than as a second accumulator.
//
// The partials are strided **row-major over the slab**: `[r][slab][n]`, so
// MODE 1 sums a contiguous KSLABS for each row and the arena is
// MAXROWS times what it was.

#include "llm_common.glsl"

#ifndef MODE
#define MODE 0
#endif
#ifndef KSLABS
#define KSLABS 4
#endif

#define TILE 16
#define WAVE 64

// Rows of A this dispatch carries. See the header: a specialization constant,
// bounded by MAXROWS so the accumulators stay in registers.
layout(constant_id = 0) const uint ROWS = 1;
#ifndef MAXROWS
#define MAXROWS 3 // OCR's builds are 16: a page's regions decode together (OCR.md O11)
#endif

#ifdef Q4B
#include "llm_q4k.glsl"
#endif

layout(local_size_x = WAVE) in;

void main() {
#if MODE == 0
    uint slab = gl_WorkGroupID.x;                // which stripe of K
    uint nt = gl_WorkGroupID.y;                  // which 16 output columns
    uint ktiles = pc.gemmK / TILE;
    uint perSlab = ktiles / KSLABS;
    uint kt0 = slab * perSlab;

    uint lane = gl_LocalInvocationID.x;
    uint col = lane % TILE;                      // the output column this lane owns
    uint sub = lane / TILE;                      // which of the four tiles of a step
    uint xbase = pc.xnOff + kt0 * TILE;

    float sum[MAXROWS];
    [[unroll]] for (uint r = 0u; r < MAXROWS; r++) {
        sum[r] = 0.0;
    }
#ifdef Q4B
    // Every row is on the plane: the fp16 tail left with D13's payoff (P2),
    // so a quantised matrix is quantised all the way through.
    {
        uint nsb = pc.gemmK >> 8;
        uint nk = pc.gemmN * pc.gemmK;
        // P3a's plane sits between the tiles and the records, so both bases
        // are still derived and `QK_HIGH_BYTES` is zero without -DQ5B.
        uint high0 = (pc.bOff + (nk >> 1)) >> 2;
        uint rec0 = (pc.bOff + (nk >> 1) + QK_HIGH_BYTES(nk)) >> 2;
        // A tile is 32 words and a lane owns two of them — the eight k
        // either side of `col`'s sixteen — with `sub` picking which of the
        // step's four tiles, the way lane*4 does on the Q8 arm.
        uint qbase = (pc.bOff >> 2) + (nt * ktiles + kt0) * 32u + sub * 32u + col * 2u;
        // The same index without the buffer base is the plane's byte index,
        // because a high byte covers exactly the word it is named by.
        uint hbi = (nt * ktiles + kt0) * 32u + sub * 32u + col * 2u;
        uint curSB = 0xffffffffu;
        uvec4 rec = uvec4(0u);
        for (uint c = 0u; c < perSlab; c += 4u) {
            uint g = (kt0 + c + sub) >> 1;       // a 32-group is two k-tiles
            uint sb = g >> 3;
            if (sb != curSB) {
                curSB = sb;
                uint idx = rec0 + ((nt * nsb + sb) * TILE + col) * 4u;
                rec = uvec4(w8[idx], w8[idx + 1u], w8[idx + 2u], w8[idx + 3u]);
            }
            uint sc, mn;
            q4kScaleMin(g & 7u, uvec3(rec.y, rec.z, rec.w), sc, mn);
            vec2 dd = unpackHalf2x16(rec.x);
            float ds = dd.x * float(sc), dm = dd.y * float(mn);
            uint w = qbase + c * 32u;
            uint x = xbase + (c + sub) * TILE;
            [[unroll]] for (uint u = 0u; u < 2u; u++) {
                uint word = w8[w + u];
                uint hb = QK_HIGH_BYTE(high0, hbi + c * 32u + u);
                [[unroll]] for (uint t = 0u; t < 4u; t++) {
                    uint by = bitfieldExtract(word, int(t * 8u), 8);
                    uint e = u * 8u + t * 2u;
                    // The weight is unpacked once and multiplied into every
                    // row: this is the whole of the R-row arm.
                    float wlo = ds * float(QK_LEVEL_LO(by, hb, t)) - dm;
                    float whi = ds * float(QK_LEVEL_HI(by, hb, t)) - dm;
                    [[unroll]] for (uint r = 0u; r < MAXROWS; r++) {
                        if (r < ROWS) {
                            uint xr = x + r * pc.lda;
                            sum[r] += wlo * float(hact[xr + e]);
                            sum[r] += whi * float(hact[xr + e + 1u]);
                        }
                    }
                }
            }
        }
    }
#elif defined(Q8B)
    // Every row is on the plane here too, as int8 all the way through.
    {
        uint qbase = (pc.bOff >> 2) + (nt * ktiles + kt0) * 64u + lane * 4u;
        uint sbase = ((pc.bOff + pc.gemmN * pc.gemmK) >> 1) + nt * (pc.gemmK >> 5) * TILE + col;
        // One step is four tiles: 1024 bytes of weight, 64 halves of
        // activation, and one scale a lane — a 32-element group is two whole
        // k-tiles, so it is constant across the tile the lane owns.
        for (uint c = 0u; c < perSlab; c += 4u) {
            uint w = qbase + c * 64u;
            uint x = xbase + (c + sub) * TILE;
            float16_t d = w16[sbase + ((kt0 + c + sub) >> 1) * TILE];
            [[unroll]] for (uint u = 0u; u < 4u; u++) {
                uint word = w8[w + u];
                [[unroll]] for (uint t = 0u; t < 4u; t++) {
                    // L8b-2's exactness is a property of this product and is
                    // unchanged by the row count: the half is formed once and
                    // widened once, whichever row consumes it.
                    float wv = float(float16_t(bitfieldExtract(int(word), int(t * 8u), 8)) * d);
                    [[unroll]] for (uint r = 0u; r < MAXROWS; r++) {
                        if (r < ROWS) {
                            sum[r] += wv * float(hact[x + r * pc.lda + u * 4u + t]);
                        }
